#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char line[10002];
    // 整行读入，保留首尾及连续空格，不能只读第一个token。
    fgets(line, sizeof(line), stdin);
    int count = 0, inside_word = 0;
    for (int i = 0; line[i] != '\0'; ++i) {
        char letter = line[i];
        int is_letter = (letter >= 'a' && letter <= 'z') || (letter >= 'A' && letter <= 'Z');
        // 只有从非单词位置进入字母段的第一字母才计数。
        if (is_letter && !inside_word) {
            ++count;
        }
        inside_word = is_letter;
    }
    // count统计词段开头数，整行空格时保持0。
    printf("%d\n", count);
    return 0;
}

