#include <string>
#include <vector>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    // 读取一整行，不用只读取单个词的cin >> line。
    getline(cin, line);
    int count = 0;
    bool inside_word = false;
    for (char letter : line) {
        bool is_letter = (letter >= 'a' && letter <= 'z') || (letter >= 'A' && letter <= 'Z');
        // 前一位置不在词中、当前是字母时才开始一个新词。
        if (is_letter && !inside_word) {
            ++count;
        }
        inside_word = is_letter;
    }
    // 只输出单词数量，连续和首尾空格都不会增加答案。
    cout << count << '\n';
    return 0;
}

