import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        // 整行输入保留空格，用字符状态识别词段。
        String line = reader.readLine();
        int count = 0;
        boolean insideWord = false;
        for (char letter : line.toCharArray()) {
            boolean isLetter = (letter >= 'a' && letter <= 'z') || (letter >= 'A' && letter <= 'Z');
            // 只在词段的第一个字母加1，同词后续字母不重复计数。
            if (isLetter && !insideWord) {
                count++;
            }
            insideWord = isLetter;
        }
        // 输出统计结果，整行无字母时为0。
        System.out.println(count);
    }
}

STDIO.rust:
use std::io::{self, Read};

fn main() {
    // 保存完整输入文本，后面按空白边界遍历词段。
    let mut input = String::new();
    // 读入所有文本而非只取第一个词，行末换行也按空白处理。
    io::stdin().read_to_string(&mut input).unwrap();
    // split_whitespace只产生非空段，count得到单词数后输出。
    println!("{}", input.split_whitespace().count());
}
